// Hand-written (NOT autogenerated). Guards struct vectors, which
// tools/ulsdkbuild writes inline, one generated.Create<Struct> per element.

package message

import (
	"reflect"
	"testing"

	"github.com/urbanlogiq/ulsdk/types/schema"
)

func TestRecordBatchStructVectorsRoundTrip(t *testing.T) {
	want := &RecordBatch{
		Length:  10,
		Nodes:   []FieldNode{{Length: 10, NullCount: 1}, {Length: 10}},
		Buffers: []schema.Buffer{{Offset: 0, Length: 8}, {Offset: 8, Length: 80}},
	}
	got, err := RecordBatchFromBytes(want.ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Nodes, want.Nodes) {
		t.Fatalf("nodes = %+v, want %+v", got.Nodes, want.Nodes)
	}
	if !reflect.DeepEqual(got.Buffers, want.Buffers) {
		t.Fatalf("buffers = %+v, want %+v", got.Buffers, want.Buffers)
	}
	if got.Length != want.Length {
		t.Fatalf("length = %d, want %d", got.Length, want.Length)
	}
}
